import { expect, test, vi, describe, beforeEach } from 'vitest';
import AdminPage from './page';
import * as auth from '../lib/auth';
import * as navigation from 'next/navigation';

// Mock dependencies
vi.mock('../lib/auth', () => ({
  verifyAdmin: vi.fn(),
}));

vi.mock('next/navigation', () => ({
  forbidden: vi.fn(),
}));

describe('AdminPage', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  test('calls forbidden if not admin', async () => {
    // Setup mock to return non-admin
    (auth.verifyAdmin as any).mockResolvedValue({ isAdmin: false });

    // Execute component function
    await AdminPage();

    // Verify forbidden was called
    expect(navigation.forbidden).toHaveBeenCalled();
  });

  test('does not call forbidden if admin', async () => {
    // Setup mock to return admin
    (auth.verifyAdmin as any).mockResolvedValue({ isAdmin: true });

    // Execute component function
    await AdminPage();

    // Verify forbidden was NOT called
    expect(navigation.forbidden).not.toHaveBeenCalled();
  });
});

